/**
 * Session management commands
 *
 * Provides context for starting/resuming work sessions.
 */

import chalk from "chalk";
import type { Command } from "commander";
import {
  getReadyTasks,
  initContext,
  type KspecContext,
  type LoadedTask,
  loadAllItems,
  loadAllTasks,
  loadInboxItems,
  loadSessionContext,
  loadTriageRecords,
  ReferenceIndex,
} from "../../parser/index.js";
import {
  ShadowError,
  type ShadowSyncResult,
  shadowPull,
} from "../../parser/shadow.js";
import type { SessionContext as StoredSessionContext, ObservationType } from "../../schema/index.js";
import { loadMetaContext } from "../../parser/meta.js";
import { ulid } from "ulid";
import {
  type SessionLogSummary,
  type SessionLogDetail,
  type SessionLogStats,
  type ToolUsageStats,
  type TimePeriodStats,
  type IterationSummary,
  type SessionSearchResult,
  type SearchMatch,
  type EnvInjectionResult,
  getAllSessionLogSummaries,
  getSessionLogDetail,
  resolveSessionId,
  readEvents,
  readSessionContext,
  computeSessionLogStats,
  computeToolUsageStats,
  computeTimePeriodStats,
  listSessions,
  searchSessionEvents,
  deduplicatePhasedToolCalls,
  createSessionWithBudget,
  validateSessionId,
  injectClaudeCodeEnv,
  injectCodexEnv,
  injectGeminiEnv,
  injectOpenCodeEnv,
  getFallbackInjectionInstructions,
} from "../../sessions/store.js";
import type { SessionEvent, SessionStatus } from "../../sessions/types.js";
import {
  errors,
  hints,
  sessionHeaders,
  sessionPrompt,
} from "../../strings/index.js";
import {
  formatCommitGuidance,
  formatRelativeTime,
  type GitWorkingTree,
  getCurrentBranch,
  getRecentCommits,
  getWorkingTreeStatus,
  isGitRepo,
  parseTimeSpec,
} from "../../utils/index.js";
import { markMutating } from "../command-annotations.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, info, isJsonMode, isNoteSuperseded, output, success, warn } from "../output.js";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface CheckpointResult {
  /** Whether session can end cleanly */
  ok: boolean;

  /** Human-readable message for Claude Code */
  message: string;

  /** Issues that need attention before stopping */
  issues: CheckpointIssue[];

  /** Instructions for the agent */
  instructions: string[];
}

export interface CheckpointIssue {
  type: "uncommitted_changes" | "in_progress_task" | "incomplete_todo";
  description: string;
  details?: Record<string, unknown>;
}

export interface SessionContext {
  /** When this context was generated */
  generated_at: string;

  /** Current git branch */
  branch: string | null;

  /** Session context (focus, threads, questions) */
  context: StoredSessionContext | null;

  /** Tasks currently in progress */
  active_tasks: ActiveTaskSummary[];

  /** Tasks awaiting review (code done, PR pending) */
  pending_review_tasks: ActiveTaskSummary[];

  /** Recent notes from active tasks */
  recent_notes: NoteSummary[];

  /** Incomplete todos from active tasks */
  active_todos: TodoSummary[];

  /** Tasks ready to be picked up */
  ready_tasks: ReadyTaskSummary[];

  /** Blocked tasks with blockers */
  blocked_tasks: BlockedTaskSummary[];

  /** Recently completed tasks */
  recently_completed: CompletedTaskSummary[];

  /** Recent git commits */
  recent_commits: CommitSummary[];

  /** Unified activity timeline (merged tasks + commits, deduplicated) */
  activity_timeline: ActivityItem[];

  /** Working tree status */
  working_tree: GitWorkingTree | null;

  /** Inbox items awaiting triage (oldest first) */
  inbox_items: InboxSummary[];

  /** Inbox triage statistics */
  inbox_stats: InboxStats;

  /** Unresolved observations (full mode only) */
  observations: ObservationSummary[];

  /** Summary statistics */

